META={'id':'g8-ma-hl-b','subj':'數學','name':'八上 數學 翰林 B卷','source':'翰林版 八年級數學（三）B卷（114上，教用版答案與解析；僅收選擇題）'}

sec('第1回 1-1 乘法公式')
ch(r'如附圖，將四塊紙板組合成一個大正方形，其中右上與左下的正方形面積分別為 \(a^2\) 與 \(b^2\) 平方單位，則甲、乙兩塊面積的大小關係為何？',['甲＞乙','甲＝乙','甲＜乙','條件不足，無法得知'],2,r'由圖可知，甲、乙兩塊長方形面積皆為 \(ab\)，故甲＝乙。',img=(1,415,405,512,500))
ch(r'計算 \(36.5^2-33.5^2\) 之值為何？',['9','150','210','4900'],3,r'原式＝\((36.5+33.5)(36.5-33.5)=70\times3=210\)。')
ch(r'威利使用「乘法公式」寫出以下幾個式子：\((100+5)^2=100^2+a\times100\times5+5^2\)；\((100-5)^2=100^2-2\times100\times b+5^2\)；\(101^2-99^2=(101+99)(101-c)\)；\(101\times99=(100+d)(100-d)\)。有關式子中的 \(a\)、\(b\)、\(c\)、\(d\) 何者正確？',[r'\(a=1\)',r'\(b=-5\)',r'\(c=-99\)',r'\(d=1\)'],4,r'\(a=2\)；\(b=5\)；\(c=99\)；\(d=1\)，故選(D)。')
ch('【素養】如附圖，甲是邊長為 80 的正方形，乙是長為 84、寬為 76 的長方形，則兩者面積的大小關係何者正確？',['甲比乙大 16 平方單位','甲比乙小 16 平方單位','甲比乙大 4 平方單位','甲、乙兩面積相等'],1,r'甲面積＝\(80^2\)，乙面積＝\(84\times76=(80+4)(80-4)=80^2-4^2=80^2-16\)，故甲比乙大 16 平方單位。',img=(1,372,980,512,1045))
ch('【素養】附圖黑板上的 (1)、(2) 式所對應的算式分別為何？',['甲、戊','乙、丁','丙、丁','丙、戊'],4,r'(1) \(96^2=(100-4)^2=100^2-2\times100\times4+4^2\Rightarrow\) 丙；(2) \(96\times104=(100-4)(100+4)=100^2-4^2\Rightarrow\) 戊，故選(D)。',img=(1,170,1300,488,1432))
ch(r'【素養】計算 \((199.9)^2=200^2-k\)，則 \(k\) 之值為何？',['0.01','0.81','39.99','358.21'],3,r'\((199.9)^2=(200-0.1)^2=200^2-2\times200\times0.1+(0.1)^2=200^2-39.99\Rightarrow k=39.99\)。')
ch(r'【素養】若 \(298\times302=90000-a=b\)，則下列何者正確？',[r'\(a=2\)',r'\(a=-2\)',r'\(b=89996\)',r'\(b=90004\)'],3,r'\(298\times302=(300-2)(300+2)=300^2-2^2=90000-4=89996\Rightarrow a=4\)，\(b=89996\)。')
ch(r'【素養】若 \(m=201^2-3^2\)，則下列何者不是 \(m\) 的因數？',['2','7','11','17'],2,r'\(m=(201+3)(201-3)=204\times198=2^3\times3^3\times11\times17\)，則因數沒有 7。')
ch(r'【素養】已知 \(x=2018\times2022\)，\(y=2020\times2020\)，\(z=2019\times2021\)，則 \(x\)、\(y\)、\(z\) 的大小關係為何？',[r'\(x>y>z\)',r'\(y>x>z\)',r'\(z>x>y\)',r'\(y>z>x\)'],4,r'\(x=(2020-2)(2020+2)=2020^2-4\)，\(y=2020^2\)，\(z=(2020-1)(2020+1)=2020^2-1\)，得 \(y>z>x\)。')
ch('【素養】判斷下列各式的值，何者最大？',[r'\(49\times10^2-10^2\)',r'\(36\times10^2-20^2\)',r'\(25\times8^2-40^2\)',r'\(9\times20^2-20^2\)'],1,r'(A) \(7^2\times10^2-10^2=70^2-10^2=80\times60\)；(B) \(6^2\times10^2-20^2=60^2-20^2=80\times40\)；(C) \(5^2\times8^2-40^2=40^2-40^2=0\)；(D) \(3^2\times20^2-20^2=60^2-20^2=80\times40\)，比較可得(A)最大。')
psg('安琪和艾美一起在飲料店打工，安琪說：「我發現一杯 30 元的蜜香紅茶一天可以賣出 30 杯。」艾美說：「我也有發現蜜香紅茶每降價 1 元，一天可以多賣出一杯耶！」【素養題】')
ch('【素養】依照艾美的說法，一杯蜜香紅茶降價 5 元賣的話，則一天的收入會比原價 30 元賣出時，多或少幾元？',['多 150 元','多 25 元','少 25 元','少 150 元'],3,r'所求＝\((30-5)(30+5)-30^2=30^2-5^2-30^2=-25\)，故一天的收入會少 25 元。',img=(1,550,1080,1003,1295))
ch('【素養】已知蜜香紅茶成本為每杯 10 元，某天飲料店以一杯 20 元作為售價來販售，則當天這款飲料賺多少元？',['400','480','520','600'],1,r'售價 20 元，即降價 10 元，則可多賣出 10 杯，所求＝\((30-10)(30+10)-10\times(30+10)=20\times40-10\times40=(20-10)\times40=400\)（元）。',img=(1,550,1080,1003,1295))
endp()

sec('第2回 1-2 多項式的加減')
ch(r'下列各組的配對中，有幾組是同類項？(甲) \(-3x\) 和 \(-3x^2\)；(乙) \(4^2y\) 和 \(4y\)；(丙) \(7x\) 和 \(-7x\)；(丁) \(9y^2\) 和 \(\dfrac{1}{9}y^2\)',['1','2','3','4'],3,r'(乙)(丙)(丁) 中的配對是同類項。')
ch('下列各個多項式中，哪一個是升冪排列？',[r'\(5x+3x^2-x^3+7\)',r'\(2x^3+x^2-4x+6\)',r'\(-2+4x^3-x^2-5x\)',r'\(-7-5x+4x^2+3x^3\)'],4,r'只有(D)依照 \(x\) 的次數由低至高排列。')
ch(r'計算 \((x^2+2x+5)+(3x^2+6x+4)=\)？',[r'\(4x^2+8x+9\)',r'\(3x^2+12x+20\)',r'\(4x^2+17x\)',r'\(21x^2\)'],1,r'原式＝\((x^2+3x^2)+(2x+6x)+(5+4)=4x^2+8x+9\)。')
ch(r'已知多項式 \(-x+\dfrac{1}{3}x^3+\dfrac{3}{4}\) 中，三次項係數為 \(a\)，二次項係數為 \(b\)，一次項係數為 \(c\)，而常數項為 \(d\)，則 \(a\)、\(b\)、\(c\)、\(d\) 的大小關係為何？',[r'\(d>a>b>c\)',r'\(d>c>b>a\)',r'\(c>b>a>d\)',r'\(a>b>c>d\)'],1,r'\(a=\dfrac{1}{3}\)，\(b=0\)，\(c=-1\)，\(d=\dfrac{3}{4}\Rightarrow d>a>b>c\)。')
ch(r'【素養】下列各式中，屬於 \(x\) 的多項式有多少個？\(\dfrac{6}{x}-17\)、\(4x^2-|6x|+9\)、\(\dfrac{2x}{5}\)、\(3x+8=0\)、\(-10\)、\(2x+|19|\)',['2','3','4','5'],2,r'在 \(x\) 的多項式中，\(x\) 不能在分母與絕對值中，且不能有等號，故正確的有 \(\dfrac{2x}{5}\)、\(-10\)、\(2x+|19|\)，共 3 個。')
ch(r'【素養】計算 \(-(y^2-3)+(2y^2-5y+6)\) 的結果，則下列敘述何者錯誤？',['二次項係數為 0',r'一次項為 \(-5y\)','常數項為 9','化簡後有三項'],1,r'原式＝\(-y^2+3+2y^2-5y+6=y^2-5y+9\)，二次項係數為 1，故(A)錯誤。')
ch(r'【素養】計算 \((5x^2-3x)+(1-6x+8x^2)=ax^2+bx+c\)，則 \(a-b+c\) 之值為何？',['5','11','17','23'],4,r'原式＝\(13x^2-9x+1\Rightarrow a=13\)，\(b=-9\)，\(c=1\Rightarrow a-b+c=23\)。')
ch('【素養】關於多項式的加減問題，下列三位同學的敘述何者正確？',['翰哥：我發現一件驚人的事情，不論這個多項式是幾次多項式，只要相加或相減任何多項式，根本不會影響到多項式的次數！','阿強：我認為三次多項式加減四次多項式的結果，依然還是三次多項式。','小林：多項式不論是加法或減法，因為都是式子的運算，只有同類項才能合併計算。','三人皆正確'],3,r'多項式不論相加或相減，最後以 \(x\) 次方最高者來確定次數，故翰哥與阿強觀念皆有錯誤。')
ch(r'【素養】已知一個三次多項式最多可以有 \(m\) 項，最少只有 \(n\) 項，則 \(m+n=\)？',['3','4','5','6'],3,r'三次式最多有 4 項，最少有 1 項，故 \(m+n=5\)。')
psg(r'威利家的頂樓有甲、乙、丙三座不同容量的水塔，容量分別為甲 \((7x^2-11)\)、乙 \((2x^2-3x+18)\)、丙 \((-x^2+12x+5)\) 公升，如附圖所示。【素養題】')
ch('【素養】當甲、乙兩座水塔裝滿水的時候，將合計有多少公升的水量？',[r'\(9x^2-14x+18\)',r'\(9x^2-3x+7\)',r'\(5x^2-14x+18\)',r'\(5x^2-3x+7\)'],2,r'所求＝\((7x^2-11)+(2x^2-3x+18)=9x^2-3x+7\)（公升）。',img=(3,550,905,1005,1100))
ch(r'【素養】威利家某天一早原本三座水塔都裝滿水，而威利起床如廁後使用 \((-x^2+2x)\) 公升的水沖馬桶，並用 \(x\) 公升的水洗手，在沒有其他用水以及在還沒補水進水塔的情況下，三座水塔裡合計剩下多少公升的水？',[r'\(11x^2+10x+12\)',r'\(10x^2+12x+18\)',r'\(9x^2+10x+6\)',r'\(9x^2+6x+12\)'],4,r'所求＝\((7x^2-11)+(2x^2-3x+18)+(-x^2+12x+5)-(-x^2+2x)-x=9x^2+6x+12\)（公升）。',img=(3,550,905,1005,1100))
ch(r'【素養】在下課的時候，有四位同學在討論數學作業中的某一題目。小徐：這是一個 \(x\) 的二次多項式；小劉：我算一下，各項係數和為 32；小翰：\(x^2\) 項的係數恰好是 \(x\) 項係數的 11 倍；小林：多項式的常數項比 \(x\) 項係數多 6。如果他們的敘述都正確，根據討論可推出這個多項式的 \(x^2\) 項係數應為何？',['22','9','6','－7'],1,r'設 \(x\) 項係數為 \(t\)，則 \(x^2\) 項係數為 \(11t\)，常數項為 \(t+6\)；\(11t+t+(t+6)=32\Rightarrow13t=26\Rightarrow t=2\)，故 \(x^2\) 項係數為 22。')
endp()

sec('第3回 1-3 多項式的乘除')
ch(r'若多項式 \(5x^3\times\)＿＿＝\(-20x^5\)，則空格內應填入下列何者？',[r'\(-4x\)',r'\(-4x^2\)',r'\(15x\)',r'\(-25x^2\)'],2,r'所求＝\((-20x^5)\div(5x^3)=-4x^2\)。')
ch(r'計算 \((-1+4x)(-1-4x)=\)？',[r'\(1-16x^2\)',r'\(1+16x^2\)',r'\(-1-16x^2\)',r'\(-1+16x^2\)'],1,r'原式＝\((-1)^2-(4x)^2=1-16x^2\)。')
ch(r'計算 \(3x\cdot(5x+1)=\)？',[r'\(15x^2+3x\)',r'\(15x+3\)',r'\(18x\)',r'\(9x^2\)'],1,r'原式＝\(15x^2+3x\)。')
ch(r'求 \((6x^2-7x+21)\div(x+1)\) 的商式為何？',[r'\(6x-13\)',r'\(6x-1\)',r'\(6x+8\)','6'],1,r'\((6x^2-7x+21)\div(x+1)=6x-13\cdots\cdots34\)，得商式為 \(6x-13\)。')
ch(r'【素養】如附圖，妙麗在一張邊長為 \((5x+3)\) 公分的正方形紙卡上，剪下一個長、寬分別為 \((3x-1)\)、\((x+2)\) 公分的長方形，則剩餘紙張的面積為多少平方公分？',[r'\(x^2+35x+7\)',r'\(22x^2+25x-7\)',r'\(22x^2+35x-11\)',r'\(22x^2+25x+11\)'],4,r'所求面積＝\((5x+3)^2-(3x-1)(x+2)=(25x^2+30x+9)-(3x^2+5x-2)=22x^2+25x+11\)。',img=(5,390,935,513,1088))
ch(r'【素養】若 \(A\) 為 \(x\) 的三次多項式，\(B\) 為 \(x\) 的四次多項式，則下列敘述何者正確？',[r'\(A+B\) 可能為 \(x\) 的三次多項式',r'\(A-B\) 必為 \(x\) 的四次多項式',r'\(A\times B\) 應為 \(x\) 的十二次多項式',r'\(A\div B\) 的商式必為 \(x\) 的一次多項式'],2,r'(A) 應為 \(x\) 的四次多項式；(C) 應為 \(x\) 的七次多項式；(D) 除式次數高於被除式，商式為 0。')
ch(r'【素養】已知 \(A\) 為 \(x\) 的二次多項式，則下列何者不可能是 \(A\div(3x)\) 的餘式？',['0',r'\(-\dfrac{1}{7}\)','12',r'\(-x\)'],4,r'餘式可能為 0 或餘式次數小於除式次數（即常數），故 \(-x\) 不可能。')
ch(r'【素養】威利用直式乘法運算求 \((3x+5)(4x-2)\) 的結果，完整算式如附圖所示，下列有關 \(a\)、\(b\)、\(c\) 的敘述何者正確？',[r'\(a=6\)',r'\(b=20\)',r'\(c=14\)',r'\(a>b\)'],3,r'\(a=-2\times3=-6\)，\(b=4\times3=12\)，\(c=-6+20=14\)，\(a<b\)。',img=(5,880,370,1003,485))
ch(r'【素養】一個 \(x\) 的三次多項式除以 \(x\) 的二次多項式的結果，下列何者不可能發生？',[r'商式為 \(5x\)，餘式為 \(-2\)',r'商式為 \(-5x+8\)，餘式為 \(3x\)',r'商式為 \(2x-1\)，餘式為 \(x+3\)',r'商式為 \(-3x\)，餘式為 \(x^2+2x\)'],4,r'餘式次數必小於除式次數或餘式為 0，故(D)不可能發生。')
psg(r'美林公園預定地是一塊長 \((6x+4)\) 公尺、寬 \((5x+2)\) 公尺的矩形土地，如圖(一)所示。設計師阿中的方案是規劃三條寬度皆為 \(x\) 公尺的道路，如圖(二)所示；而另一名設計師阿強的方案是在對角線的區域，設計一條兩邊平行的道路，如圖(三)所示。已知兩位設計師的方案中，道路以外的區域都規劃為草坪，可做為野餐用或舉辦市集。【素養題】')
ch('【素養】在圖(二)中，草坪的面積為多少平方公尺？',[r'\(20x^2+26x+8\)',r'\(20x^2+24x+8\)',r'\(15x^2+22x+8\)',r'\(15x^2+20x+8\)'],3,r'將道路往右、下方移，草坪長為 \((6x+4)-x=5x+4\)，寬為 \((5x+2)-2x=3x+2\)，故草坪面積＝\((5x+4)(3x+2)=15x^2+22x+8\)（平方公尺）。',img=(5,550,1020,1005,1215))
ch('【素養】在圖(三)中，道路的面積為多少平方公尺？',[r'\(\dfrac{1}{2}x^2\)',r'\(5x^2+3x\)',r'\(5x^2+19x+8\)',r'\(25x^2+29x+8\)'],2,r'\(\overline{AC}=6x+4\)，\(\overline{BC}=5x+2\)，\(\overline{CD}=(6x+4)-x=5x+4\)，\(\overline{CE}=(5x+2)-x=4x+2\)，道路面積＝\(\dfrac{1}{2}(6x+4)(5x+2)-\dfrac{1}{2}(5x+4)(4x+2)=5x^2+3x\)（平方公尺）。',img=(5,550,1020,1005,1215))
ch('【素養】在多項式除法的各種觀念中，請判斷下列敘述正確的有多少個？(甲) 一個二次多項式除以一個零次多項式一定會整除；(乙) 一個二次多項式除以一個二次多項式，必定會整除；(丙) 一個二次多項式除以一個一次多項式，若有餘式，則餘式的次數必為一次；(丁) 一個係數皆為整數的二次多項式除以一個係數皆為整數的一次多項式，其商式的各項係數亦皆為整數',['4','3','2','1'],4,r'(甲) 正確；(乙) 不一定；(丙) 餘式為常數，零次；(丁) 不一定，故選(D)。')
endp()

sec('第4回 2-1 平方根的意義')
ch(r'計算 \(\left(\sqrt{\dfrac{3}{4}}\right)^2=\)？',[r'\(\dfrac{9}{16}\)',r'\(\dfrac{3}{16}\)',r'\(\dfrac{9}{4}\)',r'\(\dfrac{3}{4}\)'],4,r'\(\left(\sqrt{\dfrac{3}{4}}\right)^2=\dfrac{3}{4}\)。')
ch(r'若 \(A=\sqrt{65}\)、\(B=8\)、\(C=\sqrt{63}\)，試比較 \(A\)、\(B\)、\(C\) 的大小關係為何？',[r'\(A>B>C\)',r'\(B>A>C\)',r'\(C>B>A\)',r'\(A>C>B\)'],1,r'\(A=\sqrt{65}\)，\(B=8=\sqrt{64}\)，\(C=\sqrt{63}\)，因為 \(65>64>63\)，所以 \(A>B>C\)。')
ch(r'計算 \(\sqrt{2^6\times5^2\times7^4}=\)？',['3841600','3920','1960','84'],3,r'\(\sqrt{2^6\times5^2\times7^4}=2^3\times5\times7^2=1960\)。')
ch(r'\(1\dfrac{9}{16}\) 的平方根為何？',[r'\(1\dfrac{3}{4}\)',r'\(\pm1\dfrac{3}{4}\)',r'\(1\dfrac{1}{4}\)',r'\(\pm1\dfrac{1}{4}\)'],4,r'\(1\dfrac{9}{16}=\dfrac{25}{16}\) 的平方根為 \(\pm\sqrt{\dfrac{25}{16}}=\pm\dfrac{5}{4}=\pm1\dfrac{1}{4}\)。')
ch(r'【素養】若 12 是 \(a\) 的正平方根，且 64 的負平方根是 \(b\)，則 \(a+b=\)？',['136','152','196','4240'],1,r'\(a=12^2=144\)，\(b=-\sqrt{64}=-8\Rightarrow a+b=144+(-8)=136\)。')
ch(r'【素養】有關 \(\sqrt{20}\) 的敘述，下列何者不正確？',[r'\(\sqrt{20}>4\)',r'面積為 20 的正方形，其邊長可記為 \(\sqrt{20}\)',r'\(\sqrt{20}\) 只能求得近似值，無法用小數表達完整且精確的數值',r'平方根通常有正有負，例如：20 的平方根有 \(\sqrt{20}\)，\(-20\) 的平方根則有 \(-\sqrt{20}\)'],4,r'(D) 20 的平方根有 \(\pm\sqrt{20}\)，但 \(-20\) 為負數，沒有平方根。')
ch('【素養】有關平方根的敘述，下列何者錯誤？',['負數沒有平方根',r'若 \(\sqrt{x}\) 恰等於 \(x\)，則 \(x\) 必為 1',r'若 \(x\) 是 \(y\) 的平方根，則 \(x^2=y\)','任意一個正整數都會有兩個平方根'],2,r'(B) \(x\) 可能為 0 或 1。')
ch(r'【素養】\(\sqrt{16}\) 的平方根為何？',[r'\(\pm4\)','2',r'\(\pm2\)','4'],3,r'\(\sqrt{16}=4\)，則 4 的平方根為 \(\pm2\)。')
ch(r'【素養】若要使用十分逼近法或直接判斷求出 \(\sqrt{12}\) 的近似值，下列敘述正確的有幾人？翰哥：\(\sqrt{4}<\sqrt{12}<\sqrt{16}\)，得到 \(2<\sqrt{12}<4\)，因此 \(\sqrt{12}\) 應該大約在 2.5 左右！小林：\(\sqrt{9}<\sqrt{12}<\sqrt{16}\)，得到 \(3<\sqrt{12}<4\)，因此 \(\sqrt{12}\) 有可能是 3.5 左右的數字。阿誠：\((3.4)^2=11.56\)，因為 \(12>11.56\)，所以 \(\sqrt{12}\) 會超過 3.4。阿琪：\((3.45)^2=11.9025\)，因為 \(12>11.9025\)，所以 \(\sqrt{12}\) 會超過 3.5。',['1','2','3','4'],2,r'翰哥設定範圍太大，應改為 \(\sqrt{9}<\sqrt{12}<\sqrt{16}\Rightarrow3<\sqrt{12}<4\)；阿琪的推論錯誤，\((3.45)^2=11.9025\)，因為 \(12>11.9025\)，所以 \(\sqrt{12}\) 會超過 3.45，不見得會超過 3.5。故小林、阿誠正確，共 2 人。')
ch(r'【素養】已知 \(x\)、\(y\) 皆為正整數，若 \(\sqrt{39+x}\) 與 \(\sqrt{39-y}\) 都是正整數，且分別為其最小值，則 \(x+y\) 之值為何？',['13','30','48','49'],3,r'\(\sqrt{39+x}=7=\sqrt{49}\Rightarrow39+x=49\Rightarrow x=10\)；\(\sqrt{39-y}=1=\sqrt{1}\Rightarrow39-y=1\Rightarrow y=38\)；\(x+y=10+38=48\)。')
psg('春節時，會將牆、門上貼上春聯，除了增加節日的喜慶氣氛，也有祈福、避邪的寓意。今博士心血來潮取了一張面積為 40 平方公分的紅紙準備提筆寫春聯。【素養題】')
ch(r'【素養】傑克操作計算機得到的數值如附圖所示（\(6.305^2=39.753025\)，\(6.315^2=39.879225\)，\(6.325^2=40.005625\)，\(6.335^2=40.132225\)），則這張春聯的邊長以四捨五入取到小數點後第二位，約為多少公分？',['6.30','6.31','6.32','6.33'],3,r'因為邊長為 \(\sqrt{40}\)，且 \(6.315^2<(\sqrt{40})^2<6.325^2\Rightarrow6.315<\sqrt{40}<6.325\)，所以取為 6.32。',img=(7,800,1215,1005,1320))
ch('【素養】若傑克再取一張面積為 15 平方公分的正方形紅紙要寫春聯，則這張春聯的周長應介於下列哪兩個正整數之間？',['3、4','4、5','14、15','15、16'],4,r'設此正方形周長為 \(x\) 公分，\(\left(\dfrac{x}{4}\right)^2=15\Rightarrow x^2=240\)，因為 \(15^2<240<16^2\)，所以 \(x\) 介於 15、16 之間。')
endp()

sec('第5回 1-1～2-1 複習')
ch(r'試比較 \(A=503^2\)、\(B=500^2+3^2\) 之大小，並計算兩者相差多少？',[r'\(A>B\)，相差 6',r'\(A=B\)，相差 0',r'\(A>B\)，相差 3000',r'\(A<B\)，相差 3000'],3,r'\(A=(500+3)^2=500^2+2\times500\times3+3^2\)，故 \(A>B\)，相差 \(2\times500\times3=3000\)。')
ch(r'判斷 \(-7\) 為 \(x\) 的幾次多項式？',['零次','一次','二次',r'\(-7\) 並非多項式'],1,r'\(-7\) 為常數多項式，即 \(x\) 的零次多項式。')
ch(r'若 \(4x\times(\quad)=\dfrac{1}{4}x^3\)，則 \((\quad)\) 應填入下列何者？',[r'\(x^2\)',r'\(16x^2\)',r'\(\dfrac{1}{16}x\)',r'\(\dfrac{1}{16}x^2\)'],4,r'所求＝\(\dfrac{1}{4}x^3\div4x=\dfrac{1}{16}x^2\)。')
ch(r'計算 \(\sqrt{(-7)^2}\) 之值為何？',['－7',r'\(\sqrt{-49}\)','7',r'\(\sqrt{7}\)'],3,r'\(\sqrt{(-7)^2}=\sqrt{49}=7\)。')
ch(r'【素養】已知 \(A\) 為三次多項式，且 \(A\div(2x-3)\) 的餘式為 \(R\)，但 \(R\neq0\)，則 \(R\) 為幾次多項式？',['零次','一次','二次','三次'],1,r'因為餘式次數必小於除式次數，且 \(R\neq0\)，所以 \(R\) 為零次多項式。')
ch(r'【素養】若 \(M\) 是 \(x\) 的三次多項式，\(N\) 也是 \(x\) 的三次多項式，則 \(M+N\) 不可能為 \(x\) 的幾次多項式？',['六次','三次','二次','零次'],1,r'三次多項式與三次多項式相加，可能是三次、二次、一次、零次多項式或零多項式，不可能是六次多項式。')
ch(r'【素養】若 \(ax^2+bx+c\) 為 \(x\) 的二次多項式，則根據多項式的定義，下列敘述中有幾個人是正確的？翰哥：既然確定是二次多項式，那麼 \(a\) 就不能為 0；小林：雖然是二次多項式，但是一次項也不能消失，所以 \(b\) 不能是 0；阿誠：二次多項式的判定其實與 \(c\) 無關，所以 \(c\) 是什麼數字都可以',['3','2','1','0'],2,r'二次多項式中，對一次項沒有限制，故 \(b\) 亦可以是 0，故小林錯誤；翰哥、阿誠正確，共 2 人。')
ch(r'【素養】若 \((x^2-4x+6)\div(x-2)\) 的商式為 \(ax+b\)，餘式為 \(c\)，則 \(a+b+c=\)？',['－5','－1','1','5'],3,r'\((x^2-4x+6)\div(x-2)=x-2\cdots\cdots2\Rightarrow a=1\)，\(b=-2\)，\(c=2\)，則 \(a+b+c=1\)。')
ch('【素養】老師在課堂上出了一張皆為是非題的考卷，如附圖所示（某生的作答：1.(○) 面積為 7 的正方形，無法表示其邊長；2.(×) √100＝10，則 √10＝1；3.(○) 任意非 0 的整數皆有一正一負的平方根；4.(×) √16＝±4；5.(○) 0 的平方根為 0）。若每題 20 分，滿分為 100 分，未作答以及答錯皆不給分亦不倒扣，請判斷這張考卷應該得到幾分？',['20','40','60','80'],3,r'1. (×) 可以用 \(\sqrt{7}\) 表示其邊長；2. (×) \(\sqrt{10}\neq1\)；3. (×) 負整數沒有平方根；4. (×) \(\sqrt{16}=4\)；5. (○)。答錯第 1、3 兩題，得分應為 60 分。',img=(9,630,705,940,905))
psg('翰和建設公司針對一塊邊長為 99.7 公尺的正方形公園用地進行規劃，附圖是公園內部遊樂設施配置的草稿圖。【素養題】')
ch(r'【素養】這塊土地的實際面積若為 \(A\) 平方公尺，則 \(A\) 最接近以下哪一個正整數？',['9900','9940','9990','10000'],2,r'\(A=99.7^2=(100-0.3)^2=100^2-2\times100\times0.3+0.3^2=10000-60+0.09=9940.09\)，故最接近(B) 9940。',img=(9,820,950,1003,1120))
ch(r'【素養】已知草稿圖畫在一張面積為 99.7 平方公分的畫紙上，若此畫紙的邊長為 \(x\) 公分，則 \(x\) 應介於哪兩個整數之間？',['100、101','99、100','10、11','9、10'],4,r'\(9^2<99.7<10^2\Rightarrow9<\sqrt{99.7}<10\)，即 \(9<x<10\)。',img=(9,820,950,1003,1120))
ch(r'【素養】若 \(3\times(2^2+1)\times(2^4+1)=k-4\)，則 \(k=\)？',['260','259','255','19'],2,r'\(3\times(2^2+1)\times(2^4+1)=(2^2-1)(2^2+1)(2^4+1)=(2^4-1)(2^4+1)=2^8-1=255=k-4\Rightarrow k=259\)。')
endp()

sec('第6回 2-2 根式的運算')
ch(r'比較 \(2\sqrt{5}\) 與 \(5\sqrt{2}\) 的大小關係為何？',[r'\(2\sqrt{5}>5\sqrt{2}\)',r'\(2\sqrt{5}<5\sqrt{2}\)',r'\(2\sqrt{5}=5\sqrt{2}\)','條件不足，無法比較'],2,r'\(2\sqrt{5}=\sqrt{4\times5}=\sqrt{20}\)，\(5\sqrt{2}=\sqrt{25\times2}=\sqrt{50}\)，因為 \(\sqrt{20}<\sqrt{50}\)，所以 \(2\sqrt{5}<5\sqrt{2}\)。')
ch(r'下列根式中，有幾個是最簡根式？\(\sqrt{10}\)、\(\sqrt{20}\)、\(\dfrac{3}{4}\sqrt{30}\)、\(\sqrt{\dfrac{8}{5}}\)、\(\dfrac{\sqrt{16}}{\sqrt{6}}\)、\(\sqrt{3.1}\)',['2','3','4','5'],1,r'\(\sqrt{10}\)、\(\dfrac{3}{4}\sqrt{30}\) 已無法再化簡，共 2 個。')
ch(r'計算並化簡 \(\sqrt{3}(\sqrt{6}+3\sqrt{2})=\)？',[r'\(6\sqrt{2}\)',r'\(3\sqrt{2}+3\sqrt{6}\)',r'\(\sqrt{18}+3\sqrt{6}\)',r'\(\sqrt{18}+\sqrt{6}\)'],2,r'原式＝\(\sqrt{18}+3\sqrt{6}=3\sqrt{2}+3\sqrt{6}\)。')
ch('下列各式所化成的最簡根式中，何者錯誤？',[r'\(\sqrt{2^3}=2\sqrt{2}\)',r'\(\sqrt{2^5}=4\sqrt{2}\)',r'\(\sqrt{2^7}=6\sqrt{2}\)',r'\(\sqrt{2^9}=16\sqrt{2}\)'],3,r'\(\sqrt{2^7}=\sqrt{2^6\times2}=2^3\sqrt{2}=8\sqrt{2}\)。')
ch(r'【素養】利用平方差公式將 \(\dfrac{1}{\sqrt{3}-2}\) 有理化分母後，可得下列何者？',[r'\(\sqrt{3}+2\)',r'\(\sqrt{3}-2\)',r'\(-\sqrt{3}+2\)',r'\(-\sqrt{3}-2\)'],4,r'\(\dfrac{1}{\sqrt{3}-2}=\dfrac{\sqrt{3}+2}{(\sqrt{3}-2)(\sqrt{3}+2)}=\dfrac{\sqrt{3}+2}{3-4}=-\sqrt{3}-2\)。')
ch(r'【素養】若 \((2\sqrt{7}-3\sqrt{3})^2=a+b\sqrt{21}\)，則 \(a-b=\)？',['－1','5','43','67'],4,r'\((2\sqrt{7}-3\sqrt{3})^2=(2\sqrt{7})^2-12\sqrt{21}+(3\sqrt{3})^2=55-12\sqrt{21}\Rightarrow a=55\)，\(b=-12\)，\(a-b=55-(-12)=67\)。')
ch(r'【素養】若 \(\sqrt{17}\) 的整數部分為 \(a\)，小數部分為 \(b\)，則下列何者正確？',[r'\(a=4\)',r'\(a=3\)',r'\(b=5-\sqrt{17}\)',r'\(b=\sqrt{17}-3\)'],1,r'\(\sqrt{17}\approx4.\cdots\)，整數部分 \(a=4\)，小數部分 \(b=\sqrt{17}-4\)。')
ch(r'【素養】解方程式 \(\sqrt{6}x-20=\sqrt{2}x\)，則 \(x=\)？',['5','10',r'\(5\sqrt{6}+5\sqrt{2}\)',r'\(10\sqrt{6}+10\sqrt{2}\)'],3,r'將常數移項可得 \(\sqrt{6}x-\sqrt{2}x=20\Rightarrow x=\dfrac{20}{\sqrt{6}-\sqrt{2}}=\dfrac{20(\sqrt{6}+\sqrt{2})}{6-2}=5\sqrt{6}+5\sqrt{2}\)。')
ch(r'【素養】課堂上老師出了一個題目：\(\sqrt{5}+\sqrt{7}\) 與 \(\sqrt{12}\) 哪一個數比較大呢？翰哥：我覺得是一樣大，\(5+7=12\)，所以 \(\sqrt{5}+\sqrt{7}=\sqrt{5+7}=\sqrt{12}\)。小林：雖然我不知道答案，但 \(\sqrt{5}+\sqrt{7}\) 的計算並非 \(\sqrt{5+7}\)，自然不會等於 \(\sqrt{12}\)。阿誠：雖然 \(\sqrt{5}+\sqrt{7}\neq\sqrt{5+7}\)，但是答案應該還是一樣大的，因為 \((\sqrt{5}+\sqrt{7})^2=(\sqrt{5})^2+(\sqrt{7})^2=5+7=12\) 且 \((\sqrt{12})^2=12\)，兩邊平方後的結果既然一樣大，原數值一樣大無誤。有幾位的說法是正確的呢？',['3','2','1','0'],3,r'\((\sqrt{5}+\sqrt{7})^2=(\sqrt{5})^2+(\sqrt{7})^2+2\times\sqrt{5}\times\sqrt{7}=12+2\sqrt{35}\)，\((\sqrt{12})^2=12\)，得 \(\sqrt{5}+\sqrt{7}>\sqrt{12}\)。翰哥、阿誠皆錯誤，小林雖然不知道答案，但說法是正確的，故 1 人正確。')
ch(r'【素養】關於 \(\sqrt{3}\) 這個數的敘述，下列何者錯誤？',[r'在數線上找不到 \(\sqrt{3}\)',r'\(1.7<\sqrt{3}<1.8\)',r'\(\sqrt{3}+\sqrt{3}+\sqrt{3}=\sqrt{27}\)',r'\(\sqrt{3}\times\sqrt{3}\times\sqrt{3}=3\sqrt{3}\)'],1,r'(A) 可在數線上找到 \(\sqrt{3}\)；(B) \((1.7)^2=2.89<3<(1.8)^2=3.24\)；(C) \(\sqrt{3}+\sqrt{3}+\sqrt{3}=3\sqrt{3}=\sqrt{27}\)；(D) 正確。')
psg(r'博士請威利、洛基和傑克三人各自用不同長的繩子圍出一塊面積為 50 平方公分的四邊形。威利：我的是正方形；洛基：我的長方形短邊是 \(\sqrt{8}\) 公分；傑克：我的長方形短邊是 \(\sqrt{2}\) 公分。【素養題】')
ch(r'【素養】已知 \(\sqrt{2}\approx1.414\)，\(\sqrt{3}\approx1.732\)，\(\sqrt{5}\approx2.236\)，請問威利圍出的正方形邊長約為多少公分？',['4.472','7.07','11.312','13.856'],2,r'\(\sqrt{50}=5\sqrt{2}\approx5\times1.414=7.07\)（公分）。',img=(11,550,975,1005,1225))
ch('【素養】威利、洛基和傑克哪一個人圍出的四邊形周長最長？',['威利','洛基','傑克','無法比較'],3,r'威利：周長＝\(5\sqrt{2}\times4=20\sqrt{2}\)；洛基：\(\sqrt{8}=2\sqrt{2}\)，另一邊長＝\(\dfrac{50}{2\sqrt{2}}=\dfrac{25}{2}\sqrt{2}\)，周長＝\(\left(2\sqrt{2}+\dfrac{25}{2}\sqrt{2}\right)\times2=29\sqrt{2}\)；傑克：另一邊長＝\(\dfrac{50}{\sqrt{2}}=25\sqrt{2}\)，周長＝\((\sqrt{2}+25\sqrt{2})\times2=52\sqrt{2}\)，故傑克圍成的四邊形周長最長。',img=(11,550,975,1005,1225))
endp()

sec('第7回 2-3 畢氏定理')
ch(r'已知一個直角三角形的兩股長分別為 6 和 \(\sqrt{13}\)，則斜邊長為多少？',[r'\(\sqrt{23}\)','7','8',r'\(\sqrt{65}\)'],2,r'斜邊長＝\(\sqrt{6^2+(\sqrt{13})^2}=\sqrt{49}=7\)。')
ch(r'如附圖，試以畢氏定理計算圖形中未知的邊長 \(b=\)？',['24',r'\(\sqrt{46}\)','4',r'\(2\sqrt{6}\)'],4,r'\(b^2+(\sqrt{11})^2=(\sqrt{35})^2\Rightarrow b^2=24\Rightarrow b=\pm\sqrt{24}=\pm2\sqrt{6}\)（負不合）。',img=(13,440,545,515,630))
ch(r'已知坐標平面上 \(A(3,1)\)、\(B(-2,13)\) 兩點，則 \(\overline{AB}\) 的長為何？',['5','12','13',r'\(\sqrt{145}\)'],3,r'\(\overline{AB}=\sqrt{[3-(-2)]^2+(1-13)^2}=\sqrt{5^2+(-12)^2}=\sqrt{169}=13\)。')
ch(r'如附圖，\(\angle ACB=\angle BDC=90^\circ\)，\(\overline{AC}=\sqrt{10}\)，\(\overline{CD}=3\)，\(\overline{BD}=\sqrt{6}\)，則 \(\overline{AB}=\)？',['5',r'\(5\sqrt{2}\)','6',r'\(6\sqrt{2}\)'],1,r'\(\overline{BC}=\sqrt{3^2+(\sqrt{6})^2}=\sqrt{15}\)，\(\overline{AB}=\sqrt{(\sqrt{10})^2+(\sqrt{15})^2}=\sqrt{25}=5\)。',img=(13,405,770,520,895))
ch('【素養】如附圖，有一圓柱體杯子，上方杯蓋中央有一小孔，將一支長 40 公分的玻棒從孔插入杯底邊緣，發現玻棒露出杯口外的長度有 10 公分，若杯底內部圓直徑為 36 公分，則圓柱體杯子的高度為多少公分？（不考慮玻棒的粗細）',['4','12','18','24'],4,r'玻棒在內部的長度為 \(40-10=30\)（公分），圓柱體底面的半徑為 \(36\div2=18\)（公分），設圓柱體高度為 \(h\) 公分，則 \(18^2+h^2=30^2\)，得 \(h=\pm24\)（負不合）。',img=(13,425,940,515,1052))
ch('【素養】下列有關畢氏定理的敘述，何者錯誤？',['證明畢氏定理的方法不只一種','畢氏定理講述的內容即是直角三角形中，股與股與斜邊之間的比例會符合 3：4：5','以直角三角形的三邊長為直徑，作出三個半圓，則以兩股為直徑的兩個半圓面積和會等於以斜邊為直徑的半圓面積','以直角三角形的兩股為邊長，分別作出的兩個正方形面積和會等於以斜邊為邊長的正方形面積'],2,r'(B) 畢氏定理講述的內容是直角三角形中，兩股長的平方和等於斜邊長的平方。')
ch(r'【素養】如附圖，若每一個轉角都是直角，則 \(A\) 點至 \(B\) 點的直線距離為何？',['26','36','50',r'\(\sqrt{541}\)'],1,r'連接 \(A\)、\(B\) 兩點，並以 \(A\) 點水平延伸作 \(\overline{AC}\)，\(\overline{AC}=3+9+12=24\)，\(\overline{BC}=13-(8-5)=10\)，利用畢氏定理得 \(\overline{AB}=\sqrt{10^2+24^2}=26\)。',img=(13,860,365,1005,452))
ch('【素養】已知一三角形的三邊長之比為 5：12：13，若三角形的面積為 270，則其周長為何？',['30','45','60','90'],4,r'因為三邊長之比為 5：12：13，所以為直角三角形。設三邊長為 \(5k\)、\(12k\)、\(13k\)（\(k\neq0\)），則面積＝\(5k\times12k\times\dfrac{1}{2}=270\Rightarrow k=\pm3\)（負不合），得三邊長為 15、36、39，周長＝90。')
ch(r'【素養】如附圖，正方形 \(BEFG\) 的邊長為 5。長方形 \(ABCD\) 中，\(\overline{AD}=10\)，\(\overline{AB}=3\)，且 \(E\)、\(B\)、\(C\) 在同一直線上，則 \(\overline{DF}=\)？',[r'\(5\sqrt{5}\)',r'\(2\sqrt{41}\)','17','20'],3,r'延長 \(\overline{DC}\) 與 \(\overline{FG}\) 交於 \(H\) 點，\(\overline{FH}=5+10=15\)，\(\overline{DH}=3+5=8\)，\(\overline{FD}=\sqrt{15^2+8^2}=17\)。',img=(13,840,668,1005,772))
psg(r'過年期間，威利一家和叔叔相約到翰林運動公園的遊樂區遊玩，該公園的示意圖如附圖所示，其中 \(\angle ADB=90^\circ\)，\(\overline{AD}=120\) 公尺，\(\overline{BD}=\overline{BC}=90\) 公尺，在不計路寬的情況下作答。【素養題】')
ch(r'【素養】從 1 號停車場到遊樂區的直線距離 \(\overline{AC}\) 為多少公尺？',['150','210','240','330'],3,r'\(\overline{AB}=\sqrt{120^2+90^2}=150\)（公尺），\(\overline{AC}=150+90=240\)（公尺）。',img=(13,550,1035,1005,1182))
ch(r'【素養】已知威利家的汽車停在 1 號停車場，叔叔的汽車停在 2 號停車場，爸爸停好車先去找叔叔會合，再沿道路 \(D\to B\to C\) 走到遊樂區。而威利則是從 1 號停車場沿直線路徑 \(A\to B\to C\) 到遊樂區。若爸爸和威利同時從 \(A\) 點出發，分別以每分鐘 30 公尺、20 公尺的速率前進，且中途未停下來，則爸爸比威利早還是晚幾分鐘到遊樂區？',['早 2 分鐘','早 1 分鐘','晚 1 分鐘','晚 2 分鐘'],1,r'爸爸花了 \((120+90+90)\div30=10\)（分鐘），威利花了 \(240\div20=12\)（分鐘），故爸爸比威利早 2 分鐘到遊樂區。',img=(13,550,1035,1005,1182))
ch(r'【素養】如附圖，長方形 \(ABCD\) 中，\(N\) 點在 \(\overline{BC}\) 上，且 \(\overline{AN}\perp\overline{DN}\)，若 \(\overline{AN}=12\)，\(\overline{DN}=9\)，則長方形 \(ABCD\) 周長為何？',[r'\(\dfrac{111}{5}\)',r'\(\dfrac{222}{5}\)',r'\(\dfrac{333}{5}\)',r'\(\dfrac{444}{5}\)'],2,r'如圖，作 \(\overline{MN}\) 為 \(\triangle AND\) 斜邊上的高，\(\overline{AD}=\sqrt{9^2+12^2}=15\)，\(\dfrac{1}{2}\times15\times\overline{MN}=\dfrac{1}{2}\times9\times12\Rightarrow\overline{MN}=\dfrac{36}{5}=\overline{AB}\)，長方形 \(ABCD\) 周長＝\(2\times\left(15+\dfrac{36}{5}\right)=\dfrac{222}{5}\)。',img=(14,420,75,518,152))
endp()

sec('第8回 3-1 提公因式與乘法公式作因式分解')
ch('有關公因式的判斷，下列敘述何者錯誤？',[r'\(x\) 為 \(-2x\) 和 \(7x\) 的公因式',r'\(3x\) 為 \(6x^2\) 和 \(-9x\) 的公因式',r'\(x+1\) 為 \(x+1\) 和 \(x^2+1\) 的公因式',r'\(x+2\) 為 \(-(x+2)\) 和 \(7x(x+2)\) 的公因式'],3,r'(C) \(x+1\) 不是 \(x^2+1\) 的因式。')
ch(r'已知 \(3x^2+13x-10=(x+5)(3x-2)\)，則下列何者不是 \(3x^2+13x-10\) 的因式？',[r'\(3x-2\)',r'\(x+5\)',r'\(x-5\)','3'],3,r'\(x-5\) 無法整除該多項式，故不是 \(3x^2+13x-10\) 的因式。')
ch(r'利用平方差公式，因式分解 \(9x^2-169=\)？',[r'\((9x+13)(9x-13)\)',r'\((3x+13)(3x-13)\)',r'\((3x-13)^2\)',r'\((9x-13)^2\)'],2,r'\(9x^2-169=(3x)^2-13^2=(3x+13)(3x-13)\)。')
ch(r'【素養】利用乘法公式，因式分解 \(25x^2-110x+121=\)？',[r'\((5x-11)^2\)',r'\((5x+11)^2\)',r'\((5x+11)(5x-11)\)',r'\((25x+11)(25x-11)\)'],1,r'\(25x^2-110x+121=(5x)^2-2\times5x\times11+11^2=(5x-11)^2\)。')
ch(r'【素養】已知 \((11x-6)(29x-8)-(11x-6)(9x-2)\) 可因式分解為 \(a(11x+b)(cx-3)\)，其中 \(a\)、\(b\)、\(c\) 皆為整數，則 \(a+b+c\) 之值為何？',['5','6','17','18'],2,r'原式＝\((11x-6)[(29x-8)-(9x-2)]=(11x-6)(20x-6)=2(11x-6)(10x-3)\Rightarrow a=2\)，\(b=-6\)，\(c=10\)，\(a+b+c=6\)。')
ch(r'【素養】將 \(3x^2-x(x+4)\) 因式分解，可得下列何者？',[r'\(x(2x+4)\)',r'\(2x(x-2)\)',r'\(3x(x+4)\)',r'\(2x(x+2)\)'],2,r'\(3x^2-x(x+4)=x[3x-(x+4)]=x(2x-4)=2x(x-2)\)。')
ch(r'【素養】已知 \(2x^2+2x-12=(x+3)(2x-4)\)，則下列敘述正確的有幾個？(甲) \(x+3\) 是 \(2x^2+2x-12\) 的因式；(乙) \(2x-4\) 是 \(2x^2+2x-12\) 的倍式；(丙) 2 是 \(2x^2+2x-12\) 的因式；(丁) \(2x+6\) 是 \(2x^2+2x-12\) 的因式；(戊) \(x-2\) 是 \(2x^2+2x-12\) 的倍式',['1','2','3','4'],3,r'\(2x^2+2x-12=2(x+3)(x-2)\)，\(x+3\)、\(2x-4\)、\(x-2\)、\(2x+6\)、2 皆是 \(2x^2+2x-12\) 的因式，故(甲)(丙)(丁)正確。')
ch(r'【素養】已知 \((4x-3)+(4x^2-3x)\) 可因式分解為 \((4x-3)(x-a)\)，則 \(a\) 之值為何？',['2','1','0','－1'],4,r'\((4x-3)+(4x^2-3x)=(4x-3)\times1+(4x-3)\times x=(4x-3)(x+1)\)，則 \(a=-1\)。')
ch(r'【素養】為了使得 \(x+1\) 成為 \((2x+1)(x-3)\) 的因式，需將 \((2x+1)(x-3)\) 加上或減去何數？',['減去 2','減去 4','加上 2','加上 4'],2,r'\((2x+1)(x-3)=2x^2-5x-3=(2x-7)(x+1)+4\)，故減去 4 之後便可整除。')
ch(r'【素養】若 \(x-2\) 與 \(x+6\) 皆為 \(x^2-ax+b\) 的因式，則 \((a+b)(a-b)\) 之值為何？',['－160','－128','128','160'],2,r'\((x-2)(x+6)=x^2+4x-12\)，對照係數可得 \(a=-4\)，\(b=-12\)，則 \((a+b)(a-b)=a^2-b^2=(-4)^2-(-12)^2=16-144=-128\)。')
psg(r'如附圖，博士家中有一塊長方形花圃 \(ABCD\)，有預留一塊面積為 \((x^2+8x+16)\) 平方公尺的正方形 \(AEFG\) 作為日式造景，其餘面積都要用來種花，已知 \(\overline{GD}=4x\) 公尺，\(\overline{BE}=(x-4)\) 公尺。【素養題】')
ch(r'【素養】請問博士家中正方形 \(AEFG\) 造景區域的周長為多少公尺？',[r'\(4x+4\)',r'\(4x+8\)',r'\(4x+12\)',r'\(4x+16\)'],4,r'\(x^2+8x+16=(x+4)^2\)，邊長為 \((x+4)\) 公尺，周長＝\(4(x+4)=4x+16\)（公尺）。',img=(15,840,982,1008,1105))
ch(r'【素養】已知扣除造景區域後剩餘的種花面積可以用 \((ax+b)(cx+d)\) 平方公尺表示，且 \(a\)、\(b\)、\(c\)、\(d\) 皆為整數，則 \(a+b+c+d=\)？',['6','8','14','22'],1,r'\(\overline{AD}=(x+4)+4x=5x+4\)，\(\overline{AB}=(x+4)+(x-4)=2x\)，剩餘種花面積＝\(2x(5x+4)-(x^2+8x+16)=9x^2-16=(3x+4)(3x-4)\)，\(a+b+c+d=3+4+3-4=6\)。',img=(15,840,982,1008,1105))
endp()

sec('第9回 3-2 利用十字交乘法因式分解')
ch(r'因式分解 \(x^2+2x-8=\)？',[r'\((x+2)(x+4)\)',r'\((x-2)(x+4)\)',r'\((x+2)(x-4)\)',r'\((x-2)(x-4)\)'],2,r'利用十字交乘法：\(x^2+2x-8=(x-2)(x+4)\)。')
ch(r'因式分解 \(15x^2+x-6=\)？',[r'\((3x+2)(5x-3)\)',r'\((3x-3)(5x+2)\)',r'\((3x-2)(5x+3)\)',r'\((3x+3)(5x-2)\)'],1,r'利用十字交乘法：\(15x^2+x-6=(3x+2)(5x-3)\)。')
ch(r'因式分解 \(-12x^2+25x-7=\)？',[r'\((3x+1)(4x-7)\)',r'\((3x-1)(-4x-7)\)',r'\((-3x+1)(4x-7)\)',r'\((-3x-1)(4x-7)\)'],3,r'\(-12x^2+25x-7=-(12x^2-25x+7)=-(3x-1)(4x-7)=(-3x+1)(4x-7)\)。')
ch(r'【素養】若因式分解 \(8x^2+38x-33=\) 甲 \(\times(2x+11)\)，則甲＝？',[r'\(4x+11\)',r'\(4x+3\)',r'\(4x-11\)',r'\(4x-3\)'],4,r'\(8x^2+38x-33=(4x-3)(2x+11)\)，則甲＝\(4x-3\)。')
ch(r'【素養】有一長方形，其面積為 \(15x^2-38x-40\)，若長為 \(ax+b\)，寬為 \(cx-d\)，其中 \(a\)、\(b\)、\(c\)、\(d\) 皆為正整數，則 \(a+b-c-d\) 之值為何？',['16','4','－4','－16'],3,r'\(15x^2-38x-40=(5x+4)(3x-10)\)，因為 \(a\)、\(b\)、\(c\)、\(d\) 皆為正整數 \(\Rightarrow a=5\)，\(b=4\)，\(c=3\)，\(d=10\)，\(a+b-c-d=5+4-3-10=-4\)。')
ch(r'【素養】威利和洛基將 \(-3x^2+2x+8\) 因式分解，威利：\(-3x^2+2x+8=-(ax+b)(x-2)\)；洛基：\(-3x^2+2x+8=(cx+d)(x-2)\)。已知兩人的因式分解皆是正確的，且其中 \(a\)、\(b\)、\(c\)、\(d\) 皆為整數，則下列何者錯誤？',[r'\(a=3\)',r'\(b=-4\)',r'\(c=-3\)',r'\(d=-4\)'],2,r'\(-3x^2+2x+8=-(3x+4)(x-2)=(-3x-4)(x-2)\)，由係數比較得 \(a=3\)，\(b=4\)，\(c=-3\)，\(d=-4\)。')
ch(r'【素養】若 \((x+3)^2-(x+3)-20\) 可因式分解為 \((x+a)(x+b)\)，且 \(a<b\)，則 \(3a+b\) 之值為何？',['－1','0','1','2'],3,r'令 \(x+3=k\)，則原式＝\(k^2-k-20=(k+4)(k-5)\)，將 \(k=x+3\) 代入得 \((x+7)(x-2)\Rightarrow a=-2\)，\(b=7\)，\(3a+b=3\times(-2)+7=1\)。')
ch(r'【素養】若 \(x^2+nx-30\) 可因式分解成兩個整係數一次式的乘積，則 \(n\) 的最大值與最小值相加為何？',['0','28','30','58'],1,r'\(30=1\times30=2\times15=3\times10=5\times6\)，\(n\) 可為 \(\pm29\)、\(\pm13\)、\(\pm7\)、\(\pm1\)，最大值為 29，最小值為 －29，所求＝\(29+(-29)=0\)。')
ch(r'【素養】若 \(2x+7\) 是 \(6x^2+mx-21\) 的因式，則下列何者是 \(35x^2-4x-m\) 的因式？',[r'\(3x-3\)',r'\(5x-3\)',r'\(7x-5\)',r'\(2x+7\)'],3,r'因為 \(2x+7\) 是 \(6x^2+mx-21\) 的因式，所以 \((6x^2+mx-21)\div(2x+7)\) 的餘式為 0，可得 \((m-21)-(-6)=0\Rightarrow m=15\)，\(35x^2-4x-15=(5x+3)(7x-5)\)。')
ch(r'【素養】設 \(M=2(5x+2)^2-3(5x+2)(x-1)+(x-1)^2\)，則下列哪一個不是 \(M\) 的因式？',[r'\(9x+5\)',r'\(4x+3\)',r'\(4x-3\)',r'\(-9x-5\)'],3,r'令 \(5x+2=a\)，\(x-1=b\)，則 \(M=2a^2-3ab+b^2=(2a-b)(a-b)\)，將 \(a\)、\(b\) 代回可得 \([2(5x+2)-(x-1)][(5x+2)-(x-1)]=(9x+5)(4x+3)\)，則 \(9x+5\)、\(4x+3\)、\(-9x-5\) 皆為其因式，故選(C)。')
psg(r'妙麗剪裁了三張長方形的紙卡甲、乙、丙，三張紙卡的面積分別為甲 \((6x^2+13x+6)\)、乙 \((3x^2+8x+4)\)、丙 \((5x^2+13x+6)\)，如附圖所示。已知長方形甲、乙、丙的長和寬皆為一次多項式，且係數為整數。【素養題】')
ch('【素養】已知長方形甲和長方形乙有一邊的邊長相同，則下列何者是甲和乙的相同邊長？',[r'\(x+2\)',r'\(2x+1\)',r'\(2x+3\)',r'\(3x+2\)'],4,r'甲：\(6x^2+13x+6=(2x+3)(3x+2)\)；乙：\(3x^2+8x+4=(x+2)(3x+2)\)，相同邊長為 \(3x+2\)。',img=(17,575,1040,1000,1105))
ch('【素養】妙麗發現在不裁切、不重疊的情況下，長方形乙和丙可以緊密排成一個大長方形丁，則大長方形丁的周長為何？',[r'\(16x+10\)',r'\(18x+14\)',r'\(19x+16\)',r'\(20x+18\)'],2,r'乙：\(3x^2+8x+4=(x+2)(3x+2)\)；丙：\(5x^2+13x+6=(x+2)(5x+3)\)，以 \(x+2\) 為一邊長緊密排在一起，丁的另一邊長為 \((3x+2)+(5x+3)=8x+5\)，丁的周長＝\(2[(x+2)+(8x+5)]=18x+14\)。',img=(17,575,1040,1000,1105))
endp()

sec('第10回 2-2～3-2 複習')
ch('下列算式及敘述何者正確？',[r'\(\dfrac{\sqrt{2}}{5}\) 是最簡根式',r'\(\sqrt{2}\times\sqrt{5}=2\sqrt{5}\)',r'\(\sqrt{2}+\sqrt{5}=\sqrt{7}\)',r'\(6\sqrt{3}-4\sqrt{3}=2\)'],1,r'(B) \(\sqrt{2}\times\sqrt{5}=\sqrt{10}\)；(C) \(\sqrt{2}+\sqrt{5}\neq\sqrt{7}\)；(D) \(6\sqrt{3}-4\sqrt{3}=2\sqrt{3}\)。')
ch(r'利用畢氏定理，計算附圖直角三角形中，邊長 \(x\) 的值為何？',[r'\(\sqrt{79}-\sqrt{15}\)',r'\(\sqrt{94}\)','64','8'],4,r'\(x=\sqrt{(\sqrt{79})^2-(\sqrt{15})^2}=\sqrt{79-15}=\sqrt{64}=8\)。',img=(19,405,540,515,608))
ch(r'如附圖，直角三角形中，\(\angle ACB=90^\circ\)，\(\overline{CD}\perp\overline{AB}\)，若 \(\overline{BC}=10\)，\(\overline{AC}=24\)，則 \(\overline{CD}=\)？',['26','13',r'\(\dfrac{120}{13}\)',r'\(\dfrac{60}{13}\)'],3,r'\(\overline{AB}=\sqrt{10^2+24^2}=26\)，依斜邊上的高觀念得 \(10\times24=26\times\overline{CD}\Rightarrow\overline{CD}=\dfrac{120}{13}\)。',img=(19,395,680,520,752))
ch(r'已知 \(4x^2-10x-6=2(2x+1)(x-3)\)，則下列何者是 \(4x^2-10x-6\) 的因式？',[r'\(2x-3\)',r'\(4x+2\)',r'\(x+3\)',r'\(2x-1\)'],2,r'\(4x^2-10x-6=2(2x+1)(x-3)=(4x+2)(x-3)\)。')
ch(r'【素養】若 \(66x^2+x-2=(6x+a)(bx+c)\)，其中 \(a\)、\(b\)、\(c\) 均為整數，則 \(a+b+c=\)？',['12','14','24','26'],1,r'\(66x^2+x-2=(6x-1)(11x+2)\Rightarrow a=-1\)，\(b=11\)，\(c=2\)，\(a+b+c=12\)。')
ch(r'【素養】若 \(A=\dfrac{8}{5}\)、\(B=\sqrt{\dfrac{8}{5}}\)、\(C=\dfrac{\sqrt{8}}{5}\)、\(D=\dfrac{8}{\sqrt{5}}\)，比較 \(A\)、\(B\)、\(C\)、\(D\) 四數的大小關係為何？',[r'\(A>B>C>D\)',r'\(D>C>B>A\)',r'\(D>A>B>C\)',r'\(A>D>C>B\)'],3,r'\(A=\dfrac{8}{5}=\dfrac{\sqrt{64}}{5}\)，\(B=\sqrt{\dfrac{8}{5}}=\dfrac{\sqrt{40}}{5}\)，\(C=\dfrac{\sqrt{8}}{5}\)，\(D=\dfrac{8}{\sqrt{5}}=\dfrac{8\sqrt{5}}{5}=\dfrac{\sqrt{320}}{5}\)，得 \(D>A>B>C\)。')
ch(r'【素養】已知 \(\sqrt{5}\approx2.236\)，\(\sqrt{50}\approx7.071\)，則 \(\sqrt{5000}\) 的近似值為下列何者？',['22.36','70.71','223.6','707.1'],2,r'\(\sqrt{5000}=\sqrt{50}\times\sqrt{100}=10\sqrt{50}\approx10\times7.071=70.71\)。')
ch(r'【素養】如附圖，在坐標平面上，以原點 \((0,0)\) 為圓心，並以 \(\overline{OP}\) 長為半徑畫一個圓，\(P\) 點坐標為 \((-4,3)\)，則下列哪一個點不會出現在此圓的圓周上？',[r'\(A(-6,1)\)',r'\(B(0,-5)\)',r'\(C(\sqrt{6},\sqrt{19})\)',r'\(D(\sqrt{10},\sqrt{15})\)'],1,r'\(\overline{OP}=\sqrt{(-4-0)^2+(3-0)^2}=5\)，(A) \(\overline{OA}=\sqrt{(-6-0)^2+(1-0)^2}=\sqrt{37}\neq5\)，故 \(A(-6,1)\) 不在此圓上。',img=(19,845,368,1005,468))
ch(r'【素養】試判斷 \(2\sqrt{13}-1\) 之值介於下列哪兩個整數之間？',['3、4','4、5','5、6','6、7'],4,r'\(2\sqrt{13}-1=\sqrt{52}-1\)，因為 \(\sqrt{49}<\sqrt{52}<\sqrt{64}\Rightarrow7<\sqrt{52}<8\)，則 \(6<\sqrt{52}-1<7\)。')
ch(r'【素養】設 \(\dfrac{\sqrt{11}+\sqrt{10}}{\sqrt{11}-\sqrt{10}}\) 的整數部分為 \(k\)，則 \(k=\)？',['13','41','42','43'],2,r'\(\dfrac{\sqrt{11}+\sqrt{10}}{\sqrt{11}-\sqrt{10}}=\dfrac{(\sqrt{11}+\sqrt{10})^2}{(\sqrt{11}-\sqrt{10})(\sqrt{11}+\sqrt{10})}=11+2\sqrt{110}+10=21+\sqrt{440}=21+20.\cdots=41.\cdots\)，整數部分 \(k=41\)。')
psg(r'威利和傑克參加遙控汽車大賽，以 \(A\) 點為出發點，要操控賽車順時針繞三圈回到 \(A\) 點，先抵達者獲勝，比賽規則如附圖所示：前兩圈須按照 \(A\to B\to C\to D\to A\)，最後一圈可選擇以下路徑行駛：路徑①：\(A\to B\to C\to D\to A\)；路徑②：\(A\to B\to E\to D\to A\)；路徑③：\(A\to B\to F\to D\to A\)，最先返回 \(A\) 點者獲勝！已知 \(\overline{AB}=4\) 公尺，\(\overline{BC}=10\) 公尺，\(\overline{CD}=6\) 公尺，\(E\)、\(F\) 分別為 \(\overline{BC}\) 和 \(\overline{CD}\) 的中點，且 \(\angle ABC=\angle BCD=90^\circ\)。【素養題】')
ch(r'【素養】請問圖中的 \(\overline{AD}\) 為多少公尺？',['10',r'\(\sqrt{101}\)',r'\(2\sqrt{26}\)',r'\(4\sqrt{7}\)'],3,r'作 \(\overline{AH}\perp\overline{CD}\)，\(\overline{AH}=\overline{BC}=10\)，\(\overline{DH}=6-4=2\)，\(\overline{AD}=\sqrt{10^2+2^2}=\sqrt{104}=2\sqrt{26}\)。',img=(19,605,1122,958,1312))
ch('【素養】請問在相同速率的情況下，走哪一條路徑會比較快？',['路徑①','路徑②','路徑③','無法判斷'],2,r'\(\overline{BE}=\overline{CE}=5\)，\(\overline{CF}=\overline{DF}=3\)，\(\overline{BF}=\sqrt{10^2+3^2}=\sqrt{109}\)，\(\overline{DE}=\sqrt{5^2+6^2}=\sqrt{61}\)。在圖中只要比較從 \(B\) 到 \(D\) 的路徑：\(\overline{BC}+\overline{CD}=16\)，\(\overline{BE}+\overline{DE}=5+\sqrt{61}\)（介於 12 與 13 之間），\(\overline{BF}+\overline{DF}=\sqrt{109}+3\)（介於 13 與 14 之間），可知 \(\overline{BE}+\overline{DE}\) 最短，故路徑②最快。',img=(19,605,1122,958,1312))
endp()

sec('第11回 4-1 因式分解法解一元二次方程式')
ch(r'下列各式中，有多少個一元二次方程式？(甲) \(x^2+5x+4\)；(乙) \(x^2+5x+4=0\)；(丙) \(7x+3=-2x^2\)；(丁) \(-x(4-2x)=0\)；(戊) \((x-4)^2=4\)；(己) \(2x+3y=8\)',['2','3','4','5'],3,r'(乙)(丙)(丁)(戊) 是一元二次方程式，故共有 4 個。')
ch('下列敘述何者正確？',[r'5 是 \(x^2+25=0\) 的一個解',r'\(-2\) 是 \(x^2+2x=0\) 的一個解',r'3 是 \((x-3)(3x+1)=1\) 的一個解',r'\(\dfrac{3}{5}\) 是 \((x+1)(3x-5)=0\) 的一個解'],2,r'(A) \(5^2+25\neq0\)；(B) \((-2)^2+2\times(-2)=0\)；(C) \(0\times10\neq1\)；(D) \(\dfrac{8}{5}\times\left(-\dfrac{16}{5}\right)\neq0\)。')
ch(r'若 \(x=3\) 為 \(x^2-5x+m=0\) 的一個解，則 \(m=\)？',['9','6','－4','－6'],2,r'將 \(x=3\) 代入 \(x^2-5x+m=0\)，\(3^2-5\times3+m=0\Rightarrow m=6\)。')
ch(r'解一元二次方程式 \(x^2-9=0\)，得 \(x=\)？',['9 或 －9','3 或 3','3 或 －3','3'],3,r'\(x^2-9=0\Rightarrow x^2=9\Rightarrow x=3\) 或 \(x=-3\)。')
ch(r'【素養】若 \(a\)、\(b\) 為一元二次方程式 \((3x+2)(x-5)=0\) 的兩個解，且 \(a>b\)，則 \(a-b\) 之值為何？',[r'\(-5\dfrac{2}{3}\)',r'\(-4\dfrac{1}{3}\)',r'\(4\dfrac{1}{3}\)',r'\(5\dfrac{2}{3}\)'],4,r'\((3x+2)(x-5)=0\Rightarrow x=-\dfrac{2}{3}\) 或 \(x=5\)，因為 \(a>b\)，所以 \(a=5\)，\(b=-\dfrac{2}{3}\)，\(a-b=5\dfrac{2}{3}\)。')
ch(r'【素養】若一元二次方程式 \((3x+2)(x-1)=0\)，則 \(x-1\) 之值為何？',['0','5 或 0',r'\(-\dfrac{5}{3}\) 或 0',r'\(-\dfrac{2}{3}\) 或 1'],3,r'\((3x+2)(x-1)=0\Rightarrow x=-\dfrac{2}{3}\) 或 \(x=1\Rightarrow x-1=-\dfrac{5}{3}\) 或 0。')
ch(r'【素養】若 \((m,n)\) 在坐標平面上第二象限，且 \(m^2-5m-50=0\)，\(2n^2-9n-18=0\)，則 \(m+n\) 之值為何？',[r'\(-\dfrac{13}{2}\)',r'\(\dfrac{17}{2}\)','16','1'],4,r'\(m^2-5m-50=0\Rightarrow(m+5)(m-10)=0\Rightarrow m=-5\) 或 10；\(2n^2-9n-18=0\Rightarrow(2n+3)(n-6)=0\Rightarrow n=-\dfrac{3}{2}\) 或 6。因為 \((m,n)\) 位於第二象限，所以 \(m=-5\)，\(n=6\)，\(m+n=1\)。')
ch(r'【素養】設 \(a\) 是方程式 \(6+7x+x^2=0\) 的一個解，則 \(a^2+7a-18\) 之值為何？',['－24','－12','－10','60'],1,r'將 \(x=a\) 代入得 \(a^2+7a+6=0\Rightarrow a^2+7a=-6\)，則 \(a^2+7a-18=-6-18=-24\)。')
ch('【素養】下列敘述何者正確？',[r'\(x=2\) 是 \(x^2-2x=1\) 的解',r'若一元二次方程式無常數項，以因式分解法必可解出其中一個解為 \(x=0\)',r'若一元二次方程式 \((x+3)(x-5)=1\)，可以用 \(x+3=1\) 及 \(x-5=1\) 來解得正確的 \(x\) 值',r'若一元二次方程式 \((x-2)(2x+7)=(x-2)(x-11)\)，可將等號左右兩邊同時消去 \(x-2\)，解得 \(x=4\)'],2,r'(A) 將 \(x=2\) 代入得 \(2^2-2\times2=0\neq1\)；(C) 應將方程式化成 \(A\times B=0\) 的形式，再以 \(A=0\) 或 \(B=0\) 來解；(D) 原式 \(\Rightarrow(x-2)(2x+7)-(x-2)(x-11)=0\Rightarrow(x-2)(x+18)=0\Rightarrow x=2\) 或 \(x=-18\)。')
ch(r'【素養】已知 \(x=n\) 為 \(x^2-5x-3=0\) 的一個解，則 \(4n^2-20n-3\) 之值為何？',['3','5','8','9'],4,r'\(x=n\) 代入 \(x^2-5x-3=0\) 得 \(n^2-5n-3=0\Rightarrow n^2-5n=3\)，\(4n^2-20n-3=4(n^2-5n)-3=4\times3-3=9\)。')
psg(r'貳蘭拉麵店推出優惠活動，只要使用手機完成線上闖關答題遊戲，即可獲得免費加麵或是唐揚雞一份，遊戲規則如附圖所示：問題①：已知 \(m\) 為整數，且方程式 \(x^2+mx-6=0\) 兩個解皆為整數，則 \(m\) 值有幾種可能？問題②：已知方程式 \(x^2-25x+k=0\) 的兩個解皆為質數，則 \(k\) 值為何？【素養題】')
ch('【素養】已知答對問題①，可以獲得免費加麵，則威利應該要輸入哪個選項才能答對？',['4','5','6','7'],1,r'以十字交乘法分解，\(-6=(-1)\times6=1\times(-6)=(-2)\times3=2\times(-3)\)，得 \(m\) 可能為 5、－5、1、－1，共 4 種。',img=(21,585,1108,975,1257))
ch('【素養】已知答對問題②，可以免費贈送一份唐揚雞，請問傑克要輸入哪個選項才能答對？',['136','114','84','46'],4,r'令兩解為 \(\alpha\)、\(\beta\)，\((x-\alpha)(x-\beta)=0\Rightarrow x^2-(\alpha+\beta)x+\alpha\beta=0\)，\(\alpha+\beta=25\)，由質數中唯一偶數為 2，得 \(\alpha\)、\(\beta\) 分別為 2 和 23，\(k=2\times23=46\)。',img=(21,585,1108,975,1257))
endp()

sec('第12回 4-2 配方法與公式解')
ch(r'解一元二次方程式 \(9x^2=10\)，得 \(x=\)？',[r'\(\pm\dfrac{\sqrt{10}}{3}\)',r'\(\pm\dfrac{\sqrt{10}}{9}\)',r'\(\pm1\)',r'\(\pm\dfrac{3\sqrt{10}}{10}\)'],1,r'原式 \(\Rightarrow x^2=\dfrac{10}{9}\Rightarrow x=\pm\sqrt{\dfrac{10}{9}}=\pm\dfrac{\sqrt{10}}{3}\)。')
ch(r'解一元二次方程式 \((-3x+1)^2=2\)，則 \(x=\)？',[r'\(-\dfrac{1}{3}\pm\dfrac{\sqrt{2}}{3}\)',r'\(\dfrac{1}{3}\pm\dfrac{\sqrt{2}}{3}\)',r'\(\dfrac{1}{3}\pm\sqrt{2}\)',r'\(1\pm\dfrac{\sqrt{2}}{3}\)'],2,r'\((-3x+1)^2=2\Rightarrow-3x+1=\pm\sqrt{2}\Rightarrow x=\dfrac{1}{3}\pm\dfrac{\sqrt{2}}{3}\)。')
ch(r'若 \(x^2-6x+\square\) 是一個完全平方式，則 \(\square\) 內應填何數？',['9','6','－6','－9'],1,r'\(\square=\left(-\dfrac{6}{2}\right)^2=9\)。')
ch(r'【素養】若 \(a\)、\(b\) 皆為 \(x^2-x-1=0\) 的解，則 \(a+b=\)？',['－1','0','1','2'],3,r'\(x^2-x-1=0\Rightarrow x^2-x+\dfrac{1}{4}=1+\dfrac{1}{4}\Rightarrow\left(x-\dfrac{1}{2}\right)^2=\dfrac{5}{4}\Rightarrow x=\dfrac{1\pm\sqrt{5}}{2}\)，故 \(a+b=\dfrac{1+\sqrt{5}}{2}+\dfrac{1-\sqrt{5}}{2}=1\)。')
ch(r'【素養】如附圖，威利有一個邊長為 \(a\) 的正方形甲，12 個長為 \(a\)、寬為 1 的長方形乙，則他至少準備多少個邊長為 1 的正方形丙，就能拼成一個大的正方形？',['12','24','36','144'],3,r'\(a^2+12a+\square=a^2+2\times a\times6+6^2=(a+6)^2\Rightarrow\square=6^2=36\)，故至少要 36 個正方形丙。',img=(23,375,1040,520,1115))
ch(r'【素養】若一元二次方程式 \(ax^2+5x-3=0\) 有兩個相異的解，則 \(a\) 的最小整數值為何？',['－3','－2','0','3'],2,r'\(ax^2+5x-3=0\) 有兩個相異的解，則判別式 \(5^2-4\times a\times(-3)>0\Rightarrow12a>-25\Rightarrow a>-\dfrac{25}{12}=-2\dfrac{1}{12}\)，且 \(a\neq0\)，則 \(a\) 的最小整數值為 －2。')
ch(r'【素養】將 \(x^2+9x+1\) 再加上一個數字 \(a\) 之後，會成為一個完全平方式，則 \(a=\)？',[r'\(\dfrac{9}{2}\)',r'\(\dfrac{77}{4}\)',r'\(\dfrac{81}{4}\)','80'],2,r'\(x^2+9x+(1+a)\) 為完全平方式 \(\Rightarrow1+a=\left(\dfrac{9}{2}\right)^2\Rightarrow a=\dfrac{81}{4}-1=\dfrac{77}{4}\)。')
ch(r'【素養】一元二次方程式 \(ax^2+bx+c=0\)，且 \(a\neq0\)，係數 \(a\)、\(b\)、\(c\) 對方程式解的影響，下列何者錯誤？',[r'若 \(b^2-4ac>0\)，則有兩相異解',r'若 \(b=0\)，則兩個解必互為倒數',r'若 \(c=0\)，則必有一解為 0',r'若 \(c=0\) 且 \(b\neq0\)，則必不會有重根'],2,r'(B) 若 \(b=0\Rightarrow ax^2+c=0\Rightarrow x^2=-\dfrac{c}{a}\)，若 \(-\dfrac{c}{a}<0\) 則無解；若有解，兩解互為相反數，而非倒數。')
ch(r'【素養】已知 \(k\) 為正整數，且 \(x^2-12x+k=0\) 的兩根皆為整數，則 \(k\) 的值可能為下列何者？',['16','18','23','27'],4,r'可設 \(x^2-12x+k=(x-p)(x-q)\)，則 \(k=pq>0\)，且 \(p+q=12\)，可能的 \((p,q)\) 為 (1,11)、(2,10)、(3,9)、(4,8)、(5,7)、(6,6)，則 \(k\) 的可能值為 11、20、27、32、35、36。')
psg('威利和傑克正在玩一款桌遊──神祕大富翁，每人每次都輪流投擲一次一顆 1～6 點的公正骰子，投出骰子後若使用道具卡牌，則能透過卡牌的功能使前進的點數變大，所有卡牌的功能如下：金卡：骰出 x 點，可前進 x² 格；銅卡：骰出 x 點，可前進 2x 格；銀卡：骰出 x 點，可前進 3x 格；黑卡：骰出 x 點，可前進 (x＋3) 格。已知目前在下一輪投擲骰子前，傑克在威利前面 4 格的位置，且兩人都握有四種卡牌。【素養題】')
ch('【素養】若威利想一次前進 16 格，正好能得到一顆「幸運星」，則他應該選擇使用哪一種卡牌才有機會？',['金卡','銀卡','銅卡','黑卡'],1,r'金卡：\(x^2=16\)，\(x=4\)（取正）；銀卡：\(3x=16\)，\(x=\dfrac{16}{3}\)（不合）；銅卡：\(2x=16\)，\(x=8\)（不合，大於 6 點）；黑卡：\(x+3=16\)，\(x=13\)（不合，大於 6 點），故只有使用金卡才有機會一次前進 16 格。',img=(23,565,918,995,1112))
ch('【素養】真正要進行下一輪的投擲骰子時，傑克選擇使用銀卡，而威利則使用金卡，若他們兩人剛好骰出相同的點數，然後又正好停在同一格，請問他們骰出的點數為何？',['2','3','4','5'],3,r'設兩人皆骰出 \(x\) 點，\(x^2=3x+4\Rightarrow x^2-3x-4=0\Rightarrow(x+1)(x-4)=0\Rightarrow x=-1\)（不合）或 \(x=4\)，故骰出 4 點。',img=(23,565,918,995,1112))
ch(r'【素養】翰哥利用配方法解一元二次方程式 \(2x^2-8x-6=0\)，下面是他的解題步驟，請問在哪一個步驟開始發生錯誤？',[r'第一步驟：\(x^2-4x=3\)',r'第二步驟：\(x^2-4x+\left(\dfrac{4}{2}\right)^2=3+\left(\dfrac{4}{2}\right)^2\)',r'第三步驟：\(\left(x-\dfrac{4}{2}\right)^2=3+\dfrac{8}{4}\)',r'第四步驟：\(x-\dfrac{4}{2}=\pm\sqrt{\dfrac{20}{4}}\)'],3,r'(C) 第三步驟應為 \(\left(x-\dfrac{4}{2}\right)^2=3+\dfrac{16}{4}\)。')
endp()

sec('第13回 4-3 應用問題')
ch('有三個連續正整數，其平方和為 149，則此連續三個正整數為何？',['5、6、7','6、7、8','7、8、9','8、9、10'],2,r'設三個正整數為 \(x-1\)、\(x\)、\(x+1\)，\((x-1)^2+x^2+(x+1)^2=149\Rightarrow3x^2+2=149\Rightarrow x^2=49\Rightarrow x=\pm7\)（負不合），則連續三個正整數為 6、7、8。')
ch('有一對母女，女兒的年齡比媽媽小 30 歲，4 年後，媽媽年齡剛好是女兒年齡的平方，則女兒現在是幾歲？',['2','3','6','8'],1,r'設現在女兒是 \(x\) 歲，媽媽是 \((x+30)\) 歲，依題意可列式為 \((x+30)+4=(x+4)^2\Rightarrow x^2+7x-18=0\Rightarrow(x-2)(x+9)=0\Rightarrow x=2\) 或 \(x=-9\)（不合），故女兒現在是 2 歲。')
ch(r'翰哥帶 200 元去買每本 \(x\) 元的作業簿，買 \((x+2)\) 本，找回 32 元，則作業簿每本多少元？',['12','14','16','18'],1,r'依題意可列式為 \(200-x(x+2)=32\Rightarrow x^2+2x-168=0\Rightarrow(x-12)(x+14)=0\Rightarrow x=12\) 或 \(x=-14\)（不合）。')
ch(r'已知一直角三角形中，其兩股長分別比斜邊短 20 公分和 40 公分。若設斜邊長為 \(x\) 公分，則可以列出以下哪一個方程式？',[r'\(x^2+(x+20)^2=(x+40)^2\)',r'\((x+20)^2+(x+40)^2=x^2\)',r'\((x-20)^2-(x-40)^2=x^2\)',r'\((x-20)^2+(x-40)^2=x^2\)'],4,r'斜邊長 \(x\) 公分，則兩股長分別為 \((x-20)\) 公分、\((x-40)\) 公分，依題意可列式為 \((x-20)^2+(x-40)^2=x^2\)。')
ch(r'【素養】如附圖，有一張長方形 \(ABCD\) 的紙卡，其長邊 \(\overline{AB}=10\)，若在左上及左下兩個角落分別剪去一樣大小的正方形後，剩餘的紙卡面積為 62，已知 \(\overline{EF}=2\)，則 \(\overline{AE}=\)？',['2','3','4','7'],2,r'設 \(\overline{AE}=\overline{DF}=x\)，則 \(\overline{AD}=2x+2\)，\(10(2x+2)-2x^2=62\Rightarrow-2x^2+20x-42=0\Rightarrow x^2-10x+21=0\Rightarrow(x-3)(x-7)=0\Rightarrow x=3\) 或 \(x=7\)（不合），則 \(\overline{AE}=3\)。',img=(25,405,995,522,1097))
ch('【素養】班上響應愛心捐款活動，琪琪捐的錢數是阿誠的 25 倍還多 50 元。若琪琪再多捐 100 元，恰好是阿誠的平方，則阿誠捐了多少元？',['175','30','20','5'],2,r'設阿誠捐了 \(x\) 元，依題意可列式為 \((25x+50)+100=x^2\Rightarrow x^2-25x-150=0\Rightarrow(x+5)(x-30)=0\Rightarrow x=-5\)（不合）或 \(x=30\)。')
ch(r'【素養】家電特賣會場地如附圖，廠商在長為 30 公尺、寬為 20 公尺的長方形土地上，開闢等寬的參觀步道，其中灰色部分為 4 個面積相等的展區，若展區的面積和占土地總面積的 \(\dfrac{6}{25}\)，則參觀步道的路寬為多少公尺？',['7','6','5','4'],4,r'設路寬為 \(x\) 公尺，展區面積和＝\((30-3x)(20-3x)=30\times20\times\dfrac{6}{25}\Rightarrow9x^2-150x+456=0\Rightarrow(x-4)(9x-114)=0\Rightarrow x=4\) 或 \(x=\dfrac{38}{3}\)（不合），則路寬為 4 公尺。',img=(25,415,1372,522,1452))
ch(r'【素養】為了慶祝結婚紀念日，小林去花店準備買 9 朵玫瑰花共 \(x\) 元，此時店員告訴他：「建議你再多買 \(x\) 朵，花大束包裝會氣派許多！而且總價 693 元平均下來，每一朵還比原來的單價再少 3 元。」根據上列的敘述，則 \(x\) 之值為何？',['45','63','72','90'],4,r'1 朵玫瑰原價為 \(\dfrac{x}{9}\) 元，依題意可列式為 \((9+x)\left(\dfrac{x}{9}-3\right)=693\Rightarrow x^2-18x-6480=0\Rightarrow(x-90)(x+72)=0\Rightarrow x=90\) 或 \(x=-72\)（不合）。')
ch('【素養】有一個分數的分子和分母都是正整數，且分子和分母相乘積為 455，若把分母拿去除以分子，會得到商為 2，餘數為 9，則此分數為何？',[r'\(\dfrac{35}{13}\)',r'\(\dfrac{35}{2}\)',r'\(\dfrac{13}{35}\)',r'\(\dfrac{2}{35}\)'],3,r'設分子為 \(x\)，依題意可知分母為 \(2x+9\)，\(x(2x+9)=455\Rightarrow2x^2+9x-455=0\Rightarrow(x-13)(2x+35)=0\Rightarrow x=13\) 或 \(x=-\dfrac{35}{2}\)（不合），故此分數為 \(\dfrac{13}{2\times13+9}=\dfrac{13}{35}\)。')
ch('【素養】將某正三角形的其中一個邊長增加 1，另一個邊長減少 7，第三個邊長不變，恰好成為一個直角三角形，則原正三角形之邊長為何？',['4','8','9','12'],4,r'設正三角形的邊長為 \(x\)，依題意可列式為 \((x-7)^2+x^2=(x+1)^2\Rightarrow x^2-16x+48=0\Rightarrow(x-12)(x-4)=0\Rightarrow x=12\) 或 \(x=4\)（不合）。')
psg('琪美家裡的客廳正在重新裝潢，其中一面牆要保留 80 公分 × 60 公分的長方形面積做馬賽克磁磚拼貼，地板也要用正方形磁磚重新鋪設。【素養題】')
ch('【素養】若媽媽決定要用一樣規格的正方形磁磚來拼貼，且磁磚不能切割，則以下哪一種規格不適合？（單位：公分）',['邊長 3 公分','邊長 4 公分','邊長 5 公分','邊長 10 公分'],1,r'\((60,80)=20\)，20 的因數有 1、2、4、5、10、20 皆可取作邊長，故沒有邊長為 3 公分的正方形磁磚可以剛好貼滿。',img=(25,595,1145,1005,1218))
ch(r'【素養】現有 \(A\)、\(B\) 兩款正方形地板磁磚在做挑選，如附圖所示。若選 \(A\) 磁磚，那麼用 169 塊可以鋪滿地面；而 \(B\) 磁磚的邊長比 \(A\) 磁磚多 3 公分，若選 \(B\) 磁磚的話，可以少用 69 塊的磁磚，一樣可鋪滿地面且磁磚都不需切割，請問 \(A\) 磁磚的邊長為多少公分？',['10','12','15','18'],1,r'設 \(A\) 磁磚邊長為 \(x\) 公分，\(B\) 磁磚邊長為 \((x+3)\) 公分，\(169x^2=100(x+3)^2\Rightarrow69x^2-600x-900=0\Rightarrow23x^2-200x-300=0\Rightarrow(x-10)(23x+30)=0\Rightarrow x=10\) 或 \(x=-\dfrac{30}{23}\)（不合）。',img=(25,715,1378,928,1488))
endp()

sec('第14回 第5章 統計資料處理')
ch('附圖為誠誠班上 30 位同學身高的次數分配折線圖，身高在 160～170 公分的人數占全班的百分比是多少？',['3%','9%','10%','30%'],4,r'\(\dfrac{9}{30}\times100\%=30\%\)。',img=(27,335,385,518,482))
ch('承上題，則身高未達 160 公分者占全班的百分比是多少？',['20%','30%','60%','90%'],3,r'身高未達 160 公分的人數有 \(2+4+12=18\)（人），\(\dfrac{18}{30}\times100\%=60\%\)。',img=(27,335,385,518,482))
ch('附圖是八年甲班全班同學體重的相對次數分配折線圖，若全班共 40 人，則人數最多的組別有幾人？',['5','8','10','20'],3,r'人數最多為 55～60 公斤這一組，占 25%，\(40\times25\%=10\)（人）。',img=(27,170,735,410,848))
ch('【素養】附圖是阿琪班上參加國文檢定成績的累積相對次數分配折線圖，若全班有 30 人，成績 70～90 分的學生有多少人？',['7','15','21','28'],2,r'\(90\%-40\%=50\%\)，\(30\times50\%=15\)（人）。',img=(27,330,918,520,1058))
ch('【素養】附圖是子瑜班上某次段考英語成績的累積相對次數分配折線圖，若在 80～90 分的有 5 人，則及格人數（60 分以上）有多少人？',['18','22','29','31'],4,r'全班有 \(5\div(90\%-80\%)=50\)（人），及格人數有 \(50\times(100\%-38\%)=31\)（人）。',img=(27,315,1125,520,1272))
ch('【素養】附圖是大豐國中八年級男、女學生段考國文成績的累積相對次數分配折線圖，則男、女學生成績在 70 分以上（含）的百分比各是多少？',['男：40%，女：48%','男：48%，女：40%','男：60%，女：52%','男：52%，女：60%'],1,r'男學生：\(100\%-60\%=40\%\)；女學生：\(100\%-52\%=48\%\)。',img=(27,300,1350,522,1522))
ch(r'【素養】附表為翰林國中 100 名教職員工年齡的次數分配表（20～25：11 人；25～30：24 人；30～35、35～40：汙損；40～45：18 人；45～50：12 人），若 30～35 歲及 35～40 歲職員工人數的相對次數分別為 \(m\%\)、\(n\%\)，則 \(m+n=\)？',['30','35','40','45'],2,r'\(100-(11+24+18+12)=35\Rightarrow\) 30～35 歲及 35～40 歲的總人數為 35 人，\(m\%+n\%=\dfrac{35}{100}\times100\%=35\%\Rightarrow m+n=35\)。',img=(27,635,453,975,502))
ch(r'【素養】附表是某公司 30 位員工到公司上班所花時間的累積次數分配表（5～10：6；10～15：13；15～20：\(K\)；20～25：24；25～30：30），若 15～20 分鐘這組的人數比 10～15 分鐘這組的人數多 1 人，則 \(K=\)？',['12','14','21','23'],3,r'由表格可得 \(13-6+1=K-13\Rightarrow K=21\)。',img=(27,625,613,1005,672))
ch('【素養】附圖是班上 40 位同學身高的次數分配折線圖，請判斷下列哪一個敘述是錯誤的？',['165～175 公分的人數占全班的 10%','145～165 公分的人數占全班的 75%','135～165 公分的人數占全班的 82.5%','135～155 公分的人數是 175～185 公分人數的 4 倍'],4,r'(D) 在 135～155 公分的人數為 \(3+12=15\)（人），是 175～185 公分人數（3 人）的 5 倍。',img=(27,850,718,1008,810))
ch(r'【素養】阿笨將班上同學的段考數學成績分成四組，並將資料記錄於附表，則有關表中 \(X\)、\(Y\)、\(A\)、\(B\)、\(U\)、\(V\) 的敘述，下列何者錯誤？',[r'\(X=Y\)',r'\(Y=28\)',r'\(V=4U\)',r'\(Y+A=B\)'],1,r'將表格完成，對照得 \(X=24\)，\(Y=28\)，\(A=40\)，\(B=68\)，\(U=8\)，\(V=32\)，\(X\neq Y\)，故選(A)。',img=(27,625,975,1003,1077))
psg('附表是艾美班上段考數學成績的次數分配表（50～60：4 人；60～70：9 人；70～80：12 人；80～90：7 人；90～100：汙損；合計 40 人），艾美將此表繪製出累積次數分配折線圖，如附圖所示，已知兩圖表中皆有部分汙損。【素養題】')
ch('【素養】請問艾美班上 90～100 分這組的相對次數為何？',['8%','20%','25%','40%'],2,r'90～100 分有 \(40-32=8\)（人），故相對次數為 \(\dfrac{8}{40}\times100\%=20\%\)。',img=(27,590,1255,1008,1442))
ch('【素養】請問艾美所繪製的累積次數分配折線圖中，對應在橫坐標 80 分的縱坐標應為多少？',['12','13','21','25'],4,r'對應橫坐標 80 分代表不到 80 分的累積人數，故所求為 \(4+9+12=25\)。',img=(27,590,1255,1008,1442))
endp()

sec('第15回 4-1～第5章 複習')
ch(r'判別下列哪些式子為一元二次方程式？(a) \(x^2-7x+60=0\)；(b) \(x^2+7x-60\)；(c) \(x^3-7x-60=0\)；(d) \(x^2=0\)；(e) \((2-3x)(8+5x)=0\)；(f) \((x+3)^2=1\)',['abef','acef','adef','abdf'],3,r'(b) 為多項式，非方程式；(c) 為一元三次方程式。')
ch('下列敘述何者正確？',[r'若 \(x=0\) 為一元二次方程式 \(ax^2+bx+c=0\) 的一個解，則 \(c=0\)',r'方程式 \(x(x-1)=1\) 可由 \(x=1\) 或 \(x-1=1\) 得兩解為 \(x=1\) 或 \(x=2\)','只要是一元二次方程式必有相異兩解',r'\(x=1\) 是 \(x^2=1\) 唯一的解'],1,r'(B) \(x=1\) 或 \(x=2\) 皆非方程式的解；(C) 也可能是重根或無解；(D) \(x=\pm1\)。')
ch(r'已知一元二次方程式 \(x^2-7x+k=0\) 的兩個解皆為正整數，則 \(k\) 的值可能為下列何者？',['－8','8','12','49'],3,r'若 \(k=12\)，則方程式 \(x^2-7x+12=0\) 可分解成 \((x-3)(x-4)=0\)，兩個解分別為 3、4，皆為正整數。')
ch(r'【素養】若 \(x^2-kx+16\) 為完全平方式，則 \(k=\)？',['8','4',r'\(\pm4\)',r'\(\pm8\)'],4,r'\(x^2-kx+16\) 為完全平方式 \(\Rightarrow16=\left(\dfrac{-k}{2}\right)^2\Rightarrow k^2=64\Rightarrow k=\pm8\)。')
ch('【素養】附圖是八年 C 班第一次段考數學科成績的累積相對次數分配折線圖，若全班共 30 人，則成績 40～60 分的有多少人？',['6','9','18','27'],3,r'40～60 分占 \(90\%-30\%=60\%\)，\(30\times60\%=18\)（人）。',img=(29,305,1045,520,1178))
ch('【素養】忠、孝、仁三班皆各有 40 名學生，某次段考，三個班數學的累積次數分配折線圖如附圖，請問下列敘述何者正確？',['及格人數最少的是孝班','及格人數最少的是仁班','70 分以上（含）人數最多的是忠班','70 分以上（含）人數最多的是孝班'],4,r'由圖可知，未滿 60 分累積人數最多的是忠班，故及格人數最少的是忠班；未滿 70 分累積人數最少的是孝班，故 70 分以上（含）人數最多的是孝班。',img=(29,280,1280,522,1452))
ch(r'【素養】已知坐標平面上有一點 \(M(a,a^2+2)\) 位在方程式 \(y=2x+1\) 的圖形上，則 \(M\) 點坐標為何？',[r'\((-1,1)\)',r'\((1,3)\)',r'\((2,6)\)',r'\((4,10)\)'],2,r'將 \(M\) 點代入 \(y=2x+1\) 得 \(a^2+2=2a+1\Rightarrow a^2-2a+1=0\Rightarrow(a-1)^2=0\Rightarrow a=1\)，故 \(M(1,3)\)。')
ch('【素養】有一個三位數，其值比個位數字與十位數字相乘的 9 倍少 2，且個位數字比十位數字多 3，百位數字比十位數字少 2，則此三位數為何？',['469','358','247','136'],2,r'設十位數字為 \(x\)，個位數字為 \(x+3\)，百位數字為 \(x-2\)，依題意列式為 \(100(x-2)+10x+(x+3)=x(x+3)\times9-2\Rightarrow3x^2-28x+65=0\Rightarrow(3x-13)(x-5)=0\Rightarrow x=\dfrac{13}{3}\)（不合）或 \(x=5\)，則此三位數為 358。')
ch(r'【素養】若一元二次方程式 \(ax^2-x-c=0\) 的兩個解為 \(-3\) 和 \(\dfrac{7}{2}\)，則 \(a+c=\)？',['－19','－3','19','23'],4,r'依題意可設原方程式為 \((x+3)(2x-7)=0\Rightarrow2x^2-x-21=0\Rightarrow a=2\)，\(c=21\)，\(a+c=23\)。')
psg('阿剛班上最近要做健康檢查，為此他上網查詢有關身體質量指數（BMI）資料，發現有世界衛生組織提倡的 BMI 公式：BMI＝體重（公斤）÷ 身高（公尺）²，以及近年牛津大學建議的新 BMI 公式：BMI＝體重（公斤）×1.3 ÷〔身高（公尺）×2.5〕，如附圖所示。【素養題】')
ch(r'【素養】阿剛透過計算機計算發現，當身高為 \(k\) 公分，用這兩個公式算出來的 BMI 都相同，請問 \(k\) 以四捨五入至整數位計算時，約為多少公分？',['168','174','180','192'],4,r'設體重為 \(y\) 公斤，身高為 \(x\) 公尺，\(\dfrac{y}{x^2}=\dfrac{y\times1.3}{x\times2.5}\Rightarrow1.3x=2.5\Rightarrow x=\dfrac{25}{13}=1.923\cdots\)（公尺），\(k=192.3\cdots\approx192\)（公分）。',img=(29,715,870,1000,1040))
ch('【素養】若測量當天阿剛顯示的 BMI 是 18.5，而他的體重為 59.94 公斤，已知學校使用世界衛生組織的 BMI 公式，請問阿剛的身高為多少公分？',['180','182','184','188'],1,r'設身高為 \(x\) 公尺，\(\dfrac{59.94}{x^2}=18.5\Rightarrow x^2=3.24\Rightarrow x=1.8\)（取正），故阿剛身高為 180 公分。',img=(29,715,870,1000,1040))
ch(r'【素養】若一元二次方程式 \(x^2+mx-18=0\) 的兩個解均為整數，且 \(5<m<10\)，關於 \(m\) 的敘述，下列何者正確？',[r'\(m\) 為質數',r'\(m\) 為 3 的倍數',r'\(m\) 的值恰好介於兩個解之間',r'在 \(5<m<10\) 的範圍內，沒有符合條件的 \(m\)'],1,r'依題意敘述，唯一符合的是 \((x-2)(x+9)=0\Rightarrow x^2+7x-18=0\)，則 \(m=7\)，且兩個解為 2 或 －9，故僅(A)選項正確。')
endp()
